INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Darf ein Arbeitgeber die Arbeitszeiten eines Auszubildenden gemäß § 14 Abs. 2 BBiG festlegen?', 2, '[{"text": "Ja", "correct": true, "because": "Das Weisungsrecht erlaubt die Anordnung von Arbeitszeiten"}, {"text": "Nein", "correct": false, "because": "Festlegung ist erlaubt"}]'),
('00000000-0000-0000-0000-000000000000', 'Muss ein Arbeitgeber bei der Anordnung von Arbeitszeiten die Zustimmung des Auszubildenden einholen?', 2, '[{"text": "Ja", "correct": false, "because": "Das Weisungsrecht erfordert keine Zustimmung"}, {"text": "Nein", "correct": true, "because": "Arbeitgeber hat Entscheidungsfreiheit"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann ein Arbeitgeber Überstunden für Auszubildende gemäß § 14 Abs. 2 BBiG anordnen?', 2, '[{"text": "Ja", "correct": true, "because": "Im Rahmen der gesetzlichen Grenzen möglich"}, {"text": "Nein", "correct": false, "because": "Anordnung ist zulässig"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist die Anordnung von Arbeitszeiten durch den Arbeitgeber unabhängig von Arbeitsschutzvorschriften?', 2, '[{"text": "Ja", "correct": false, "because": "ArbSchG muss eingehalten werden"}, {"text": "Nein", "correct": true, "because": "Arbeitsschutz hat Vorrang"}]'),
('00000000-0000-0000-0000-000000000000', 'Darf ein Arbeitgeber die Arbeitszeiten eines Auszubildenden täglich ändern?', 2, '[{"text": "Ja", "correct": true, "because": "Flexibilität im Weisungsrecht gegeben"}, {"text": "Nein", "correct": false, "because": "Änderungen sind erlaubt"}]');
INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Welches Gesetz gibt dem Arbeitgeber das Recht, Arbeitszeiten für Auszubildende anzuordnen?', 2, '[{"text": "BBiG § 14 Abs. 2", "correct": true, "because": "Regelt das Weisungsrecht"}, {"text": "ArbSchG", "correct": false, "because": "Regelt Arbeitsschutz"}, {"text": "KSchG", "correct": false, "because": "Regelt Kündigungsschutz"}]'),
('00000000-0000-0000-0000-000000000000', 'Was darf ein Arbeitgeber gemäß § 14 Abs. 2 BBiG in Bezug auf Arbeitszeiten tun?', 3, '[{"text": "Arbeitszeiten verbindlich festlegen", "correct": true, "because": "Teil des Weisungsrechts"}, {"text": "Arbeitszeiten nur vorschlagen", "correct": false, "because": "Festlegung ist verbindlich"}, {"text": "Arbeitszeiten ignorieren", "correct": false, "because": "Pflicht zur Anordnung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Einschränkung gilt für die Anordnung von Arbeitszeiten durch den Arbeitgeber?', 3, '[{"text": "Einhaltung von Arbeitsschutzvorschriften", "correct": true, "because": "ArbSchG schützt Auszubildende"}, {"text": "Zustimmung der Berufsschule", "correct": false, "because": "Nicht erforderlich"}, {"text": "Keine Einschränkungen", "correct": false, "because": "Gesetzliche Grenzen gelten"}]'),
('00000000-0000-0000-0000-000000000000', 'Wer hat das primäre Recht, Arbeitszeiten im Ausbildungsbetrieb festzulegen?', 2, '[{"text": "Der Arbeitgeber", "correct": true, "because": "Weisungsrecht nach § 14 Abs. 2 BBiG"}, {"text": "Der Auszubildende", "correct": false, "because": "Kein Mitbestimmungsrecht"}, {"text": "Die Berufsschule", "correct": false, "because": "Keine Zuständigkeit"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Folge hat es, wenn ein Arbeitgeber Arbeitszeiten nicht anordnet?', 3, '[{"text": "Unklare Arbeitsstruktur für Auszubildende", "correct": true, "because": "Klarheit ist erforderlich"}, {"text": "Automatische Freistellung", "correct": false, "because": "Keine gesetzliche Folge"}, {"text": "Höhere Vergütung", "correct": false, "because": "Keine Verbindung"}]');
INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Welche Rechte hat ein Arbeitgeber bei der Anordnung von Arbeitszeiten gemäß § 14 Abs. 2 BBiG?', 4, '[{"text": "Festlegung der täglichen Arbeitszeit", "correct": true, "because": "Teil des Weisungsrechts"}, {"text": "Anordnung von Pausenzeiten", "correct": true, "because": "Regelung möglich"}, {"text": "Ignorieren von Arbeitsschutzvorschriften", "correct": false, "because": "ArbSchG gilt"}, {"text": "Planung von Überstunden", "correct": true, "because": "Im Rahmen der Grenzen"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Aspekte muss ein Arbeitgeber bei der Anordnung von Arbeitszeiten beachten?', 3, '[{"text": "Arbeitsschutzgesetz (ArbSchG)", "correct": true, "because": "Schutz der Gesundheit"}, {"text": "Wünsche des Auszubildenden", "correct": false, "because": "Keine Pflicht"}, {"text": "Maximale Arbeitszeit von Jugendlichen", "correct": true, "because": "JArbSchG gilt"}, {"text": "Berufsschulzeiten", "correct": true, "because": "Freistellung erforderlich"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Konsequenzen kann eine falsche Anordnung von Arbeitszeiten haben?', 4, '[{"text": "Verstoß gegen Arbeitsschutz", "correct": true, "because": "ArbSchG-Verletzung möglich"}, {"text": "Sanktionen durch Behörden", "correct": true, "because": "Kontrolle durch Gewerbeaufsicht"}, {"text": "Automatische Kündigung", "correct": false, "because": "Keine direkte Folge"}, {"text": "Unzufriedenheit von Auszubildenden", "correct": true, "because": "Motivation sinkt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorschriften beeinflussen die Anordnung von Arbeitszeiten durch den Arbeitgeber?', 3, '[{"text": "BBiG § 14 Abs. 2", "correct": true, "because": "Grundlage des Weisungsrechts"}, {"text": "Arbeitsschutzgesetz (ArbSchG)", "correct": true, "because": "Schutzvorschriften"}, {"text": "Kündigungsschutzgesetz (KSchG)", "correct": false, "because": "Keine Relevanz"}, {"text": "Jugendarbeitsschutzgesetz (JArbSchG)", "correct": true, "because": "Schutz junger Arbeitnehmer"}]'),
('00000000-0000-0000-0000-000000000000', 'Was kann ein Arbeitgeber im Rahmen der Arbeitszeiten festlegen?', 3, '[{"text": "Beginn der Arbeitszeit", "correct": true, "because": "Teil des Weisungsrechts"}, {"text": "Ende der Arbeitszeit", "correct": true, "because": "Regelung erlaubt"}, {"text": "Urlaubszeiten", "correct": false, "because": "Andere Regelung"}, {"text": "Pausenregelung", "correct": true, "because": "Im Weisungsrecht enthalten"}]');
INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen richtig? a) Der Arbeitgeber darf Arbeitszeiten gemäß § 14 Abs. 2 BBiG anordnen. b) Auszubildende können die Arbeitszeiten frei wählen.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Weisungsrecht ja, b) ist falsch"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Arbeitsschutzvorschriften schränken die Anordnung von Arbeitszeiten ein. b) Der Arbeitgeber muss Überstunden bezahlen.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "ArbSchG ja, b) nicht zwingend"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist nicht allgemein Pflicht"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Der Arbeitgeber darf Pausen innerhalb der Arbeitszeit festlegen. b) Arbeitszeiten dürfen Berufsschulzeiten nicht beeinträchtigen.', 3, '[{"text": "Nur a) stimmt", "correct": false, "because": "Beides ist richtig"}, {"text": "Beides stimmt", "correct": true, "because": "Pausenregelung und Freistellung"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "Beides ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen korrekt? a) Das Weisungsrecht erlaubt flexible Arbeitszeiten. b) Arbeitszeiten müssen immer gleich bleiben.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Flexibilität ja, b) ist falsch"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Verstöße bei der Anordnung von Arbeitszeiten können sanktioniert werden. b) Der Arbeitgeber muss Auszubildende über Arbeitszeiten informieren.', 3, '[{"text": "Nur a) stimmt", "correct": false, "because": "Beides ist richtig"}, {"text": "Beides stimmt", "correct": true, "because": "Sanktionen und Informationspflicht"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "Beides ist richtig"}]');
